    },
    {
      "вещество": "Трегалоза",
      "содержание": "≈ 1–4 % (сухой вес)",
      "влияние": "Диграцидный сахар, служит резервом энергии; для человека — безвредный углевод, не всасывается в кишечнике."
    },
    {
      "вещество": "Эргостерол",
      "содержание": "≈ 0,5–1 % (сухой вес)",
